101		if c.Server == appv1.KubernetesInternalAPIServerAddr {
102			settings, err := db.settingsMgr.GetSettings()
103			if err != nil {
104				return nil, err
105			}
106			if !settings.InClusterEnabled {
107				return nil, status.Errorf(codes.InvalidArgument, "cannot register cluster: in-cluster has been disabled")
108			}
109		}
110		secName, err := URIToSecretName("cluster", c.Server)
111		if err != nil {
112			return nil, err
113		}
114	
115		clusterSecret := &corev1.Secret{
116			ObjectMeta: metav1.ObjectMeta{
117				Name: secName,
118			},
119		}
120	
121		err = clusterToSecret(c, clusterSecret)
122		if err != nil {
123			return nil, err
124		}
125	
126		clusterSecret, err = db.createSecret(ctx, clusterSecret)
127		if err != nil {
128			if apierrors.IsAlreadyExists(err) {
129				return nil, status.Errorf(codes.AlreadyExists, "cluster %q already exists", c.Server)
130			}
131			return nil, err
132		}
133	
134		cluster, err := SecretToCluster(clusterSecret)
135		if err != nil {
136			return nil, status.Errorf(codes.InvalidArgument, "could not unmarshal cluster secret %s", clusterSecret.Name)
137		}
138		return cluster, db.settingsMgr.ResyncInformers()
